#!/usr/bin/env node
// Bundles the mascot (mascot/main.ts, browser code) into src/mascot.gen.ts, a
// module the Worker imports and serves at a path carrying the bundle's hash, so
// the response can be cached for good. The generated file is committed;
// test:pages rebuilds it and fails when it is stale.
//
//   npm run build:mascot

import { build } from "esbuild";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = new URL("../", import.meta.url);
export const GEN_PATH = fileURLToPath(new URL("src/mascot.gen.ts", root));

export async function mascotModule() {
  const result = await build({
    entryPoints: [fileURLToPath(new URL("mascot/main.ts", root))],
    bundle: true,
    minify: true,
    format: "iife",
    target: "es2020",
    legalComments: "none",
    write: false,
    logLevel: "silent",
  });
  const js = `/*! HTMLDrop mascot. Engine from bloub, MIT, (c) 2026 Jérémy Perret: https://github.com/jeremy-prt/bloub */\n${result.outputFiles[0].text}`;
  const hash = createHash("sha256").update(js).digest("hex").slice(0, 10);
  return (
    "// Generated by scripts/build-mascot.mjs from mascot/. Do not edit; run `npm run build:mascot`.\n" +
    `export const MASCOT_PATH = "/_assets/mascot.${hash}.js";\n` +
    `export const MASCOT_JS = ${JSON.stringify(js)};\n`
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = await mascotModule();
  let prev = "";
  try {
    prev = readFileSync(GEN_PATH, "utf8");
  } catch {}
  if (next !== prev) writeFileSync(GEN_PATH, next);
  console.log(next === prev ? "src/mascot.gen.ts is up to date" : "wrote src/mascot.gen.ts");
}
